 // Operaciones remotas. Larry nunca las ejecuta: requieren confirmación.
 use crate::{git::run_git, CmdResult};

 #[tauri::command]
 pub fn git_fetch(project: String) -> CmdResult<String> {
     run_git(&project, &["fetch", "--prune"])
 }

 #[tauri::command]
 pub fn git_pull(project: String) -> CmdResult<String> {
-    run_git(&project, &["pull"])
+    run_git(&project, &["pull", "--ff-only"])
+        .map_err(|e| network_hint(&e))
 }

 #[tauri::command]
+pub fn git_stash(project: String, pop: bool) -> CmdResult<StashState> {
+    let args = if pop { ["stash", "pop"] } else { ["stash", "push"] };
+    match run_git(&project, &args) {
+        Ok(_) => Ok(StashState::Clean),
+        Err(e) if e.contains("CONFLICT") => Ok(StashState::Conflict),
+        Err(e) => Err(e),
+    }
+}

 // push: exige rama remota existente y autorización explícita
 pub fn git_push(project: String, branch: String) -> CmdResult<String> {
     run_git(&project, &["push", "origin", &branch])
 }
